/** The whole stylesheet: tokens, base and prose. */
export const css: string = "/*\n * Tempra design tokens: the one place values live (TEMPRA-8). Take 2 of the design (TEMPRA-53,\n * design/handoff/layout-take-2) set structure and type: neutral greys, a serif for concept bodies,\n * a type scale, radii and one soft shadow. No colour on purpose; the palette (TEMPRA-1) changes\n * values here and both the app and the site follow. Light and dark come from the system through\n * light-dark().\n */\n:root {\n  color-scheme: light dark;\n\n  /* Color: surfaces */\n  --tempra-color-bg: light-dark(#ffffff, #1b1b1d); /* the sheet, panels, pills */\n  --tempra-color-ground: light-dark(#f3f3f1, #121214); /* the page under them, inset fills */\n  --tempra-color-hover: light-dark(#e9e9e6, #222225);\n  --tempra-color-selected: light-dark(#e1e1dd, #2a2a2e);\n  --tempra-color-selection: light-dark(#dededa, #3a3a3d);\n\n  /* Color: text, in three steps */\n  --tempra-color-text: light-dark(#1a1a1b, #ececea);\n  --tempra-color-muted: light-dark(#6f6f73, #9a9a9e);\n  --tempra-color-faint: light-dark(#a3a3a7, #68686c);\n\n  /* Color: lines */\n  --tempra-color-border: light-dark(#e8e8e4, #2a2a2d);\n  --tempra-color-border-strong: light-dark(#d2d2ce, #3c3c40);\n\n  /* Color: links are text, underlined in running text (no colour until the palette) */\n  --tempra-color-link: var(--tempra-color-text);\n  --tempra-color-link-visited: var(--tempra-color-text);\n  --tempra-color-code-bg: var(--tempra-color-ground);\n\n  /* Elevation */\n  --tempra-shadow:\n    0 1px 2px light-dark(rgb(0 0 0 / 0.04), rgb(0 0 0 / 0.4)),\n    0 6px 24px light-dark(rgb(0 0 0 / 0.04), rgb(0 0 0 / 0.35));\n\n  /* Type */\n  --tempra-font-body:\n    -apple-system, BlinkMacSystemFont, \"SF Pro Text\", system-ui, \"Segoe UI\", Helvetica, sans-serif;\n  --tempra-font-reader:\n    \"Iowan Old Style\", \"Palatino Linotype\", Charter, Georgia, \"Times New Roman\", serif;\n  --tempra-font-mono: ui-monospace, \"SF Mono\", Menlo, monospace;\n  --tempra-font-size: 14px;\n  --tempra-line-height: 1.5;\n  --tempra-measure: 680px; /* the reader's column, with its padding */\n  --tempra-measure-reader: 34em; /* concept text: about 66 characters of the reader's serif */\n\n  /* Type scale */\n  --tempra-text-label: 11px; /* uppercase labels, marks */\n  --tempra-text-meta: 12px; /* timestamps, crumbs, small print */\n  --tempra-text-ui: 13px; /* controls, panels, the tree */\n  --tempra-text-name: 15px; /* a library's name, code in the reader */\n  --tempra-text-reader: 17px; /* concept bodies and taglines */\n  --tempra-text-h2: 22px;\n  --tempra-text-page: 28px; /* a page's heading */\n  --tempra-text-title: 36px; /* a concept's title */\n\n  /* Space */\n  --tempra-space-1: 0.25rem;\n  --tempra-space-2: 0.5rem;\n  --tempra-space-3: 1rem;\n  --tempra-space-4: 2rem;\n  --tempra-gutter: 10px; /* the frame's gutter */\n\n  /* Shape */\n  --tempra-radius: 5px; /* code */\n  --tempra-radius-mark: 3px;\n  --tempra-radius-row: 8px; /* tree rows, inputs */\n  --tempra-radius-box: 12px; /* cards, list rows */\n  --tempra-radius-card: 16px; /* the sheet, panels */\n  --tempra-radius-pill: 999px;\n}\n\n/* Element defaults for every page of the app and the site; values come from tokens.css. */\n*,\n*::before,\n*::after {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  padding: var(--tempra-space-3);\n  background: var(--tempra-color-bg);\n  color: var(--tempra-color-text);\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-font-size);\n  line-height: var(--tempra-line-height);\n  -webkit-font-smoothing: antialiased;\n}\n\n::selection {\n  background: var(--tempra-color-selection);\n}\n\nh1 {\n  margin: 0 0 var(--tempra-space-3);\n  font-size: var(--tempra-text-page);\n  font-weight: 500;\n  line-height: 1.2;\n  letter-spacing: -0.02em;\n}\n\nh2 {\n  margin: var(--tempra-space-4) 0 var(--tempra-space-2);\n  font-size: var(--tempra-font-size);\n  font-weight: 600;\n}\n\nh3 {\n  font-size: var(--tempra-text-ui);\n  font-weight: 600;\n}\n\na {\n  color: var(--tempra-color-link);\n  text-decoration: underline;\n  text-decoration-color: var(--tempra-color-border-strong);\n  text-underline-offset: 2px;\n}\n\na:visited {\n  color: var(--tempra-color-link-visited);\n}\n\na:hover {\n  text-decoration-color: currentcolor;\n}\n\n:focus-visible {\n  outline: 2px solid var(--tempra-color-text);\n  outline-offset: 2px;\n}\n\n/* A text field shows focus by its caret and a firmer edge, not the ring. */\ninput:not([type=\"checkbox\"], [type=\"radio\"], [type=\"file\"]):focus-visible,\nselect:focus-visible,\ntextarea:focus-visible {\n  outline: 1px solid var(--tempra-color-border-strong);\n  outline-offset: 0;\n  border-color: var(--tempra-color-border-strong);\n}\n\ncode,\npre,\nkbd,\nsamp {\n  font-family: var(--tempra-font-mono);\n}\n\ncode {\n  font-size: 0.92em;\n}\n\n/* A block of code or a command never widens the page: it scrolls on its own. */\npre {\n  max-width: 100%;\n  overflow-x: auto;\n}\n\nkbd {\n  padding: 1px 7px;\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-faint);\n  font-family: inherit;\n  font-size: var(--tempra-text-label);\n}\n\nhr {\n  border: 0;\n  border-top: 1px solid var(--tempra-color-border);\n}\n\n/* Controls: pills. A plain button is a ghost; .primary is the one solid action. */\nbutton,\ninput,\nselect,\ntextarea {\n  font: inherit;\n  color: inherit;\n}\n\nbutton {\n  padding: 5px 12px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-bg);\n  font-size: var(--tempra-text-ui);\n  white-space: nowrap;\n  cursor: pointer;\n}\n\nbutton:hover:not(:disabled) {\n  background: var(--tempra-color-hover);\n}\n\nbutton:disabled {\n  cursor: default;\n  opacity: 0.5;\n}\n\nbutton.primary {\n  border-color: var(--tempra-color-text);\n  background: var(--tempra-color-text);\n  color: var(--tempra-color-bg);\n  font-weight: 500;\n}\n\nbutton.primary:hover:not(:disabled) {\n  background: var(--tempra-color-text);\n  opacity: 0.85;\n}\n\n/* A text-only button: a link's look, a button's job. */\nbutton.ghost {\n  border-color: transparent;\n  background: transparent;\n  color: var(--tempra-color-muted);\n}\n\ninput:not([type=\"checkbox\"], [type=\"radio\"], [type=\"file\"]),\nselect,\ntextarea {\n  max-width: 100%;\n  padding: 5px 10px;\n  border: 1px solid var(--tempra-color-border-strong);\n  border-radius: var(--tempra-radius-row);\n  background: var(--tempra-color-bg);\n  font-size: var(--tempra-text-ui);\n}\n\ntextarea {\n  line-height: 1.5;\n}\n\nfieldset {\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n}\n\n/* A form as a column: a label over each field, choices on their own lines, actions last. */\nform.stack fieldset {\n  margin: 0 0 20px;\n  padding: 0;\n  border: 0;\n}\n\nform.stack legend {\n  margin-bottom: 6px;\n  padding: 0;\n  font-weight: 500;\n}\n\n.field {\n  display: block;\n  margin: 10px 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n.field input,\n.field select {\n  display: block;\n  width: 100%;\n  max-width: 22rem;\n  margin-top: 4px;\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-font-size);\n}\n\n.choice {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n  margin: 4px 0;\n}\n\n.indent {\n  margin: 2px 0 6px 24px;\n}\n\n.actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin-top: 8px;\n}\n\ntable {\n  border-collapse: collapse;\n}\n\nth,\ntd {\n  padding: var(--tempra-space-1) var(--tempra-space-2);\n  text-align: left;\n  vertical-align: top;\n}\n\nimg {\n  max-width: 100%;\n}\n\ndetails > summary {\n  cursor: pointer;\n}\n\n/* Text roles used across pages. */\n.muted {\n  color: var(--tempra-color-muted);\n}\n\n.faint {\n  color: var(--tempra-color-faint);\n}\n\n.small {\n  font-size: var(--tempra-text-meta);\n}\n\n.warn {\n  font-weight: 500;\n}\n\n/* An uppercase label over a group (SOURCES, LINKED FROM). */\n.label {\n  margin: 0 0 var(--tempra-space-2);\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-label);\n  font-weight: 400;\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n}\n\n/* A message about the page (saved, an error, a version in the past). */\n.notice {\n  margin: var(--tempra-space-2) 0;\n  padding: 10px 12px;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n  font-size: var(--tempra-text-ui);\n}\n\n/* A row of short labels (type, trust tier, status): kept apart, wrapping on narrow screens. */\n.chips {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: var(--tempra-space-1) var(--tempra-space-2);\n}\n\n.chip {\n  display: inline-block;\n  padding: 1px 7px;\n  border: 1px solid transparent;\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-label);\n  white-space: nowrap;\n}\n\n/* Something to act on: in the text colour (no colour until the palette). */\n.chip.warn,\n.chip.bad {\n  color: var(--tempra-color-text);\n}\n\n/* Text for screen readers only: what a symbol (a mark, an icon) means. */\n.visually-hidden {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip-path: inset(50%);\n  white-space: nowrap;\n}\n\n/*\n * How a rendered concept reads (tempra-dev: app/reader, Reading typography): the body of a\n * concept, in the app now and wherever concepts are shown later (the site, inline MCP Apps views).\n * Scoped to .prose. A serif at 17px, about 66 characters to the line, spacing in em so the rhythm\n * scales with the text. Greys, type, spacing and rules only until the palette (TEMPRA-1).\n */\n.prose {\n  max-width: var(--tempra-measure-reader);\n  color: var(--tempra-color-text);\n  font-family: var(--tempra-font-reader);\n  font-size: var(--tempra-text-reader);\n  line-height: 1.65;\n  font-kerning: normal;\n  font-optical-sizing: auto;\n  font-variant-ligatures: common-ligatures;\n  /* Figures that sit in running text; tables and markers switch to lining, tabular ones. */\n  font-variant-numeric: oldstyle-nums proportional-nums;\n  /* Quotes and stops hang into the margin where the browser can (Safari). */\n  hanging-punctuation: first allow-end;\n  /* A long URL or identifier wraps rather than pushing the column wider; words never break. */\n  overflow-wrap: break-word;\n  hyphens: manual;\n  text-size-adjust: 100%;\n}\n\n.prose > :first-child,\n.prose > [hidden]:first-child + * {\n  margin-top: 0;\n}\n\n.prose > :last-child {\n  margin-bottom: 0;\n}\n\n/* Vertical rhythm: one step between blocks, in em. */\n.prose p,\n.prose ul,\n.prose ol,\n.prose blockquote,\n.prose pre,\n.prose .table {\n  margin: 0 0 1.1em;\n}\n\n/* No line ends on a lone short word; headings are balanced across their lines. */\n.prose p,\n.prose li,\n.prose blockquote {\n  text-wrap: pretty;\n}\n\n.prose strong {\n  font-weight: 600;\n}\n\n.prose s {\n  color: var(--tempra-color-muted);\n}\n\n/* Headings: more space above than below, so each sits with what it introduces. */\n.prose h1,\n.prose h2,\n.prose h3,\n.prose h4,\n.prose h5,\n.prose h6 {\n  margin: 1.9em 0 0.5em;\n  font-family: var(--tempra-font-reader);\n  font-variant-numeric: lining-nums proportional-nums;\n  line-height: 1.25;\n  letter-spacing: -0.005em;\n  text-wrap: balance;\n  break-after: avoid;\n  /* Clear of the cluster when a contents link scrolls to it. */\n  scroll-margin-top: 72px;\n}\n\n.prose h1 {\n  font-size: 1.65em;\n  font-weight: 500;\n  letter-spacing: -0.012em;\n}\n\n.prose h2 {\n  font-size: 1.35em;\n  font-weight: 500;\n  letter-spacing: -0.01em;\n}\n\n.prose h3 {\n  font-size: 1.12em;\n  font-weight: 600;\n}\n\n.prose h4,\n.prose h5,\n.prose h6 {\n  margin-top: 1.6em;\n  font-size: 1em;\n  font-weight: 600;\n  font-variant-caps: all-small-caps;\n  letter-spacing: 0.04em;\n}\n\n.prose h5,\n.prose h6 {\n  color: var(--tempra-color-muted);\n}\n\n/* A heading straight after another needs less room. */\n.prose :is(h1, h2, h3, h4, h5, h6) + :is(h2, h3, h4, h5, h6) {\n  margin-top: 0.7em;\n}\n\n/* Links: text-coloured, a thin underline at partial strength that firms up on hover. */\n.prose a {\n  color: inherit;\n  text-decoration-line: underline;\n  text-decoration-thickness: 1px;\n  text-decoration-color: color-mix(in srgb, currentColor 38%, transparent);\n  text-underline-offset: 0.18em;\n  text-decoration-skip-ink: auto;\n}\n\n.prose a:hover {\n  text-decoration-color: currentColor;\n}\n\n/* A link the reader would not follow (an unsafe scheme) reads as text. */\n.prose a:not([href]) {\n  text-decoration: none;\n}\n\n.prose a.broken {\n  color: var(--tempra-color-muted);\n  text-decoration-line: line-through;\n  text-decoration-color: currentColor;\n}\n\n/* Lists: muted markers, figures that line up; tight lists close, loose ones like paragraphs. */\n.prose ul,\n.prose ol {\n  padding-left: 1.4em;\n}\n\n.prose li {\n  margin: 0.2em 0;\n}\n\n.prose li::marker {\n  color: var(--tempra-color-muted);\n  font-variant-numeric: lining-nums tabular-nums;\n}\n\n.prose li > p {\n  margin: 0;\n}\n\n.prose li > :is(ul, ol) {\n  margin: 0.2em 0 0;\n}\n\n.prose :is(ul, ol).loose > li {\n  margin: 0.55em 0;\n}\n\n.prose :is(ul, ol).loose > li > p + * {\n  margin-top: 0.55em;\n}\n\n.prose .tasks {\n  padding-left: 0.1em;\n  list-style: none;\n}\n\n.prose li.task {\n  display: grid;\n  grid-template-columns: auto 1fr;\n  column-gap: 0.55em;\n  align-items: baseline;\n}\n\n.prose li.task > :not(input) {\n  grid-column: 2;\n}\n\n.prose li.task > input {\n  margin: 0;\n  accent-color: var(--tempra-color-text);\n}\n\n/* Blockquotes upright: long italic passages read slowly. */\n.prose blockquote {\n  margin-left: 0;\n  margin-right: 0;\n  padding: 0 0 0 1.1em;\n  border-left: 2px solid var(--tempra-color-border-strong);\n  color: var(--tempra-color-muted);\n}\n\n.prose blockquote > :last-child {\n  margin-bottom: 0;\n}\n\n/* Code: the mono a step down, no ligatures; inline on the code grey, blocks scroll sideways. */\n.prose code {\n  padding: 0.1em 0.35em;\n  border-radius: var(--tempra-radius);\n  background: var(--tempra-color-code-bg);\n  font-family: var(--tempra-font-mono);\n  font-size: 0.86em;\n  font-variant-ligatures: none;\n  font-variant-numeric: normal;\n  box-decoration-break: clone;\n  -webkit-box-decoration-break: clone;\n}\n\n.prose pre {\n  position: relative;\n  overflow-x: auto;\n  overscroll-behavior-x: contain;\n  padding: 14px 18px;\n  border-radius: var(--tempra-radius-row);\n  background: var(--tempra-color-code-bg);\n  font-family: var(--tempra-font-mono);\n  font-size: 0.8em;\n  font-variant-ligatures: none;\n  line-height: 1.6;\n  tab-size: 2;\n  white-space: pre;\n  overflow-wrap: normal;\n}\n\n.prose pre code {\n  padding: 0;\n  border-radius: 0;\n  background: none;\n  font-size: inherit;\n}\n\n/* The fence's language, quietly above the code (generated content: not part of the text). */\n.prose pre[data-lang] {\n  padding-top: 32px;\n}\n\n.prose pre[data-lang]::before {\n  content: attr(data-lang);\n  position: absolute;\n  top: 10px;\n  left: 18px;\n  color: var(--tempra-color-faint);\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-text-label);\n  letter-spacing: 0.04em;\n  text-transform: lowercase;\n}\n\n/* What the reader shows as its markdown (raw HTML, reference links): quieter than code. */\n.prose pre.raw,\n.prose code.raw {\n  color: var(--tempra-color-muted);\n}\n\n/*\n * Tables: real tables in their own scroll container, so a wide one scrolls sideways (on a phone\n * too) instead of breaking words. Rules between rows, none between columns; the header is told\n * apart by a rule in the text colour, not by weight (a first column is often bold already).\n */\n.prose .table {\n  max-width: 100%;\n  overflow-x: auto;\n  overscroll-behavior-x: contain;\n}\n\n.prose table {\n  border-collapse: collapse;\n  font-size: 0.88em;\n  font-variant-numeric: lining-nums tabular-nums;\n  line-height: 1.5;\n}\n\n.prose th,\n.prose td {\n  padding: 0.55em 1.25em 0.55em 0;\n  border: 0;\n  border-bottom: 1px solid var(--tempra-color-border);\n  text-align: left;\n  vertical-align: top;\n  overflow-wrap: normal;\n  word-break: normal;\n  text-wrap: pretty;\n}\n\n.prose th:last-child,\n.prose td:last-child {\n  padding-right: 0;\n}\n\n.prose th {\n  border-bottom-color: var(--tempra-color-text);\n  font-weight: 600;\n  vertical-align: bottom;\n}\n\n.prose [data-align=\"center\"] {\n  text-align: center;\n}\n\n.prose [data-align=\"right\"] {\n  text-align: right;\n}\n\n.prose hr {\n  margin: 2.2em 0;\n  border: 0;\n  border-top: 1px solid var(--tempra-color-border);\n}\n\n.prose img {\n  display: block;\n  max-width: 100%;\n  height: auto;\n  margin: 0.6em 0;\n  border-radius: var(--tempra-radius-row);\n}\n\n.prose .image-dropped {\n  color: var(--tempra-color-faint);\n  font-style: italic;\n}\n\n/* Footnote markers: a source's number, small and muted, joined to its word. */\n.prose sup.fnref {\n  margin-left: 0.08em;\n  color: var(--tempra-color-muted);\n  font-size: 0.68em;\n  font-variant-numeric: lining-nums tabular-nums;\n  line-height: 0;\n  vertical-align: super;\n  white-space: nowrap;\n}\n\n.prose sup.fnref a {\n  padding: 0 0.12em;\n  color: inherit;\n  text-decoration: none;\n}\n\n.prose sup.fnref a:hover {\n  text-decoration: underline;\n}\n\n/* Changes since human verification, over the text: lines and greys only. */\n.prose ins.diff-added {\n  text-decoration: underline;\n  text-decoration-thickness: 2px;\n  text-underline-offset: 0.22em;\n}\n\n.prose del.diff-removed {\n  color: var(--tempra-color-faint);\n  text-decoration: line-through;\n}\n\n/* On a phone the column is the screen: a little less leading, the same rhythm. */\n@media (max-width: 600px) {\n  .prose {\n    line-height: 1.6;\n  }\n}\n\n/*\n * What sits around a concept body in the reader (tempra-dev: app/reader): the hover cards and the\n * selection toolbar (popovers in the top layer, placed by the app through --float-x and\n * --float-y), comment highlights (the CSS Custom Highlight API), the threads in the Comments\n * panel and the stored Markdown view. Lines and greys only (no colour until TEMPRA-1).\n */\n\n/* A popover: placed at the coordinates the app gives it, never where the browser centres one. */\n.floating {\n  position: fixed;\n  inset: auto;\n  top: var(--float-y, 0);\n  left: var(--float-x, 0);\n  margin: 0;\n  padding: 0;\n  border: 0;\n  background: none;\n  color: inherit;\n  overflow: visible;\n}\n\n/* Hover cards over footnote markers and links. */\n.tooltip {\n  max-width: 22rem;\n  padding: 8px 12px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  color: var(--tempra-color-text);\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-text-ui);\n  line-height: 1.45;\n  text-wrap: pretty;\n}\n\n.tooltip p {\n  margin: 0;\n}\n\n.tooltip p + p {\n  margin-top: 0.4em;\n}\n\n/*\n * Comments (TEMPRA-13). A thread's quote is underlined in the body (dotted; solid when its thread\n * is the one in focus); a comment being written fills its text with the selection grey. Drawn as\n * highlights, so the body's DOM never changes for them.\n */\n::highlight(tempra-comment) {\n  text-decoration-line: underline;\n  text-decoration-style: dotted;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 0.22em;\n}\n\n::highlight(tempra-comment-active) {\n  text-decoration-line: underline;\n  text-decoration-style: solid;\n  text-decoration-thickness: 2px;\n  text-underline-offset: 0.22em;\n}\n\n::highlight(tempra-comment-draft) {\n  background-color: var(--tempra-color-selected);\n}\n\n/* The selection toolbar: a pill above the selected text. */\n.selection-tools > div {\n  display: flex;\n  gap: 2px;\n  padding: 3px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  font-family: var(--tempra-font-body);\n}\n\n.selection-tools button {\n  padding: 4px 12px;\n  border: 0;\n  background: var(--tempra-color-text);\n  color: var(--tempra-color-bg);\n  font-size: var(--tempra-text-meta);\n  font-weight: 500;\n}\n\n.selection-tools button:hover:not(:disabled) {\n  background: var(--tempra-color-text);\n  opacity: 0.85;\n}\n\n/* A footnote's own text in the Contents & sources panel. */\n.note > p {\n  margin: 0;\n}\n\n.note > p + * {\n  margin-top: 0.4em;\n}\n\n/* Threads, in the Comments panel. */\n.threads {\n  display: flex;\n  flex-direction: column;\n  gap: var(--tempra-space-3);\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.thread {\n  padding: 4px 2px;\n  border-radius: var(--tempra-radius-row);\n}\n\n.thread.active {\n  outline: 1px solid var(--tempra-color-border-strong);\n  outline-offset: 4px;\n}\n\n.thread-by {\n  display: flex;\n  align-items: baseline;\n  gap: 6px;\n  font-size: var(--tempra-text-meta);\n}\n\n.thread-by strong {\n  font-weight: 500;\n}\n\n.thread-by time,\n.thread-by .faint {\n  color: var(--tempra-color-faint);\n}\n\n/* A reply sits a step in from the thread's first comment. */\n.thread .reply {\n  padding-left: 12px;\n}\n\n.quote {\n  margin: 0 0 10px;\n  padding-left: 10px;\n  border-left: 2px solid var(--tempra-color-border-strong);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  font-style: italic;\n  line-height: 1.45;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\n.quote a {\n  color: inherit;\n  text-decoration: none;\n}\n\n.comment {\n  margin: 2px 0 10px;\n  font-size: var(--tempra-text-ui);\n  line-height: 1.45;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\n/* The composer: a pill until it is used, then a card with the quote, the text and the actions. */\n.comment-form textarea,\n.reply-form textarea {\n  display: block;\n  width: 100%;\n  min-height: 2.25rem;\n  border: 0;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n  resize: vertical;\n}\n\n.comment-form {\n  padding: 12px 14px;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n}\n\n.comment-form textarea {\n  min-height: 4rem;\n  padding: 0;\n  border-radius: 0;\n  background: transparent;\n}\n\n.comment-form textarea:focus-visible {\n  outline: none;\n}\n\n.comment-form.idle {\n  padding: 0;\n  background: none;\n}\n\n.comment-form.idle textarea {\n  min-height: 0;\n  height: 2.25rem;\n  padding: 8px 14px;\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-ground);\n  resize: none;\n}\n\n.comment-form .actions,\n.reply-form .actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: 6px;\n  margin-top: 8px;\n}\n\n.reply-form textarea {\n  min-height: 0;\n  height: 2rem;\n  padding: 5px 12px;\n  border-radius: var(--tempra-radius-pill);\n  font-size: var(--tempra-text-meta);\n  resize: none;\n}\n\n.reply-form textarea:focus,\n.reply-form textarea:not(:placeholder-shown) {\n  height: 4rem;\n  border-radius: var(--tempra-radius-box);\n}\n\n.comment-form button,\n.reply-form button {\n  padding: 4px 12px;\n  font-size: var(--tempra-text-meta);\n}\n\n/* The concept as stored (the Markdown view): the file's own text, exactly as an agent reads it. */\n.raw-markdown pre {\n  margin: 0 0 var(--tempra-space-2);\n  padding: 16px 18px;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n  font-size: var(--tempra-text-ui);\n  line-height: 1.6;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\n.comments {\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n\n/*\n * The app's frame (TEMPRA-19, take 2 in TEMPRA-53). A soft ground; on it the header, the sidebar\n * (no box) and the open file as a floating sheet; the concept's context as one panel at a time,\n * a card beside the sheet, opened from a control cluster that hovers over the sheet's top right.\n * Account pages sit on the same ground in a centred column. Under 1100px the panel overlays the\n * sheet; under 900px the sidebar becomes a drawer.\n */\nbody:has(> #root),\nbody.ground {\n  padding: 0;\n  background: var(--tempra-color-ground);\n}\n\n/* ---------- Shared pieces: the brand, menus, the avatar, icon buttons ---------- */\n\n.brand {\n  color: var(--tempra-color-text);\n  font-weight: 600;\n  letter-spacing: -0.01em;\n  text-decoration: none;\n}\n\n.brand:visited {\n  color: var(--tempra-color-text);\n}\n\n.header-sep {\n  color: var(--tempra-color-faint);\n}\n\n/* A menu: a button that opens a card of links below it. */\n.menu {\n  position: relative;\n}\n\n.menu-button {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 4px 8px;\n  border: 0;\n  background: transparent;\n  color: var(--tempra-color-muted);\n}\n\n.menu-button .caret {\n  display: inline-flex;\n  color: var(--tempra-color-faint);\n}\n\n.menu-list {\n  position: absolute;\n  top: calc(100% + 6px);\n  z-index: 20;\n  display: flex;\n  flex-direction: column;\n  gap: 1px;\n  min-width: 13rem;\n  max-height: 70vh;\n  overflow: auto;\n  margin: 0;\n  padding: 6px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  list-style: none;\n  font-size: var(--tempra-text-ui);\n}\n\n.menu-list.start {\n  left: 0;\n}\n\n.menu-list.end {\n  right: 0;\n}\n\n.menu-list a,\n.menu-list button {\n  display: block;\n  width: 100%;\n  padding: 6px 10px;\n  border: 0;\n  border-radius: var(--tempra-radius-row);\n  background: none;\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-ui);\n  text-align: left;\n  text-decoration: none;\n}\n\n.menu-list a:hover,\n.menu-list button:hover:not(:disabled),\n.menu-list a[aria-current=\"page\"] {\n  background: var(--tempra-color-hover);\n}\n\n.menu-list .menu-note {\n  padding: 6px 10px 2px;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-label);\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n}\n\n/* Who is signed in, at the top of the avatar's menu. */\n.menu-list .menu-who {\n  padding: 6px 10px 4px;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n  overflow-wrap: anywhere;\n}\n\n.menu-list hr {\n  width: 100%;\n  margin: 4px 0;\n}\n\n.avatar {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 26px;\n  height: 26px;\n  padding: 0;\n  border: 0;\n  border-radius: 50%;\n  background: var(--tempra-color-selected);\n  color: var(--tempra-color-text);\n  font-size: 10px;\n  font-weight: 600;\n}\n\n/* A round button holding one 16px glyph. */\n.icon-button {\n  position: relative;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 30px;\n  height: 30px;\n  padding: 0;\n  border: 0;\n  background: transparent;\n  color: var(--tempra-color-muted);\n}\n\n.icon-button[aria-pressed=\"true\"],\n.icon-button[aria-pressed=\"true\"]:hover:not(:disabled) {\n  background: var(--tempra-color-text);\n  color: var(--tempra-color-bg);\n}\n\n.icon-button svg {\n  display: block;\n}\n\n/* A dot on a glyph: open comments exist. */\n.icon-button .dot {\n  position: absolute;\n  top: 5px;\n  right: 5px;\n  width: 7px;\n  height: 7px;\n  border: 1.5px solid var(--tempra-color-bg);\n  border-radius: 50%;\n  background: currentcolor;\n}\n\n/* ---------- Account pages: the ground, a header, a centred column ---------- */\n\n.app-header {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n  height: 52px;\n  margin: 0 10px;\n  padding: 0 20px;\n}\n\n.app-header .spacer,\n.ws-header .spacer {\n  flex: 1;\n}\n\n.page {\n  width: 100%;\n  max-width: 720px;\n  margin: 0 auto;\n  padding: 72px 24px 96px;\n}\n\n.page-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 16px;\n  margin-bottom: 28px;\n}\n\n.page-head h1 {\n  margin: 0;\n}\n\n/* The New pill: an outlined white pill with a circled plus. */\n.pill-button {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 6px 12px 6px 8px;\n  box-shadow: var(--tempra-shadow);\n}\n\n.lib-list {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.lib-list a {\n  display: block;\n  padding: 16px 18px;\n  border-radius: var(--tempra-radius-box);\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-name);\n  font-weight: 500;\n  text-decoration: none;\n}\n\n.lib-list a:hover {\n  background: var(--tempra-color-hover);\n}\n\n.lib-list .owner {\n  color: var(--tempra-color-faint);\n  font-weight: 400;\n}\n\n/* The library's open work from the daily check (TEMPRA-66): one quiet line under its name. */\n.lib-list .lib-health {\n  display: block;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n  font-weight: 400;\n}\n\n.page-foot {\n  margin: 32px 18px 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n.page-foot a {\n  color: inherit;\n}\n\n/* ---------- The workspace ---------- */\n\n.workspace {\n  display: grid;\n  grid-template-columns: 232px minmax(0, 1fr);\n  grid-template-rows: 48px minmax(0, 1fr);\n  grid-template-areas:\n    \"header header\"\n    \"sidebar main\";\n  column-gap: var(--tempra-gutter);\n  height: 100dvh;\n  padding: 0 var(--tempra-gutter) var(--tempra-gutter);\n}\n\n.workspace.has-panel {\n  grid-template-columns: 232px minmax(0, 1fr) 320px;\n  grid-template-areas:\n    \"header header header\"\n    \"sidebar main panel\";\n}\n\n.ws-header {\n  grid-area: header;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  min-width: 0;\n  padding: 0 6px 0 10px;\n}\n\n.ws-files {\n  display: none;\n}\n\n/* The sidebar sits on the ground: the search pill, the tree (which scrolls), the views. */\n.ws-sidebar {\n  grid-area: sidebar;\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  min-height: 0;\n  padding: 8px 4px 0;\n}\n\n.search-pill {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  width: 100%;\n  margin-bottom: 10px;\n  padding: 6px 8px 6px 12px;\n  box-shadow: var(--tempra-shadow);\n  color: var(--tempra-color-faint);\n  text-align: left;\n}\n\n.search-pill:hover:not(:disabled) {\n  background: var(--tempra-color-bg);\n  color: var(--tempra-color-muted);\n}\n\n.search-pill span {\n  flex: 1;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.ws-scroll {\n  flex: 1;\n  min-height: 0;\n  overflow: auto;\n  padding-bottom: 16px;\n}\n\n/* The tree: nested lists, one 30px row per folder or file, indented 14px a level. A folder's row\n   is a button that opens and closes it (a chevron turns); a file's row is a link. */\n.tree,\n.tree ul,\n.ws-views {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.tree ul {\n  padding-left: 14px;\n}\n\n.tree li {\n  margin: 0;\n}\n\n.tree-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  height: 30px;\n  margin-bottom: 2px;\n  padding: 0 10px 0 4px;\n  border-radius: var(--tempra-radius-row);\n  font-size: var(--tempra-text-ui);\n  white-space: nowrap;\n}\n\n.tree-row:hover {\n  background: var(--tempra-color-hover);\n}\n\nbutton.tree-row {\n  width: 100%;\n  border: 0;\n  background: none;\n  color: var(--tempra-color-text);\n  font: inherit;\n  font-size: var(--tempra-text-ui);\n  font-weight: 500;\n  text-align: left;\n}\n\nbutton.tree-row:hover:not(:disabled) {\n  background: var(--tempra-color-hover);\n}\n\nbutton.tree-row[aria-current=\"page\"] {\n  background: var(--tempra-color-selected);\n}\n\n.tree-chevron {\n  flex: none;\n  display: flex;\n  width: 16px;\n  color: var(--tempra-color-faint);\n  transition: transform 0.15s ease;\n}\n\n.tree-row[aria-expanded=\"true\"] .tree-chevron {\n  transform: rotate(90deg);\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .tree-chevron {\n    transition: none;\n  }\n}\n\n.tree-name {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.tree-row > a {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  color: var(--tempra-color-muted);\n  text-decoration: none;\n  text-overflow: ellipsis;\n}\n\n.tree-row:has(> [aria-current=\"page\"]) {\n  background: var(--tempra-color-selected);\n}\n\n.tree-row > a[aria-current=\"page\"] {\n  color: var(--tempra-color-text);\n  font-weight: 500;\n}\n\n.tree-leaf {\n  flex: none;\n  width: 16px;\n}\n\n/* Marks: ● an agent's change in the last minutes, ∗ changed since the last visit, open comments,\n   a clock (stale) or an hourglass (stale soon). */\n.tree-mark {\n  flex: none;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-label);\n  font-variant-numeric: tabular-nums;\n}\n\n.tree-note {\n  padding: 4px 10px;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n}\n\n.ws-views {\n  margin-top: 20px;\n}\n\n.ws-views a {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  height: 30px;\n  margin-bottom: 2px;\n  padding: 0 10px 0 28px;\n  border-radius: var(--tempra-radius-row);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n  text-decoration: none;\n}\n\n.ws-views a:hover {\n  background: var(--tempra-color-hover);\n}\n\n.ws-views a[aria-current=\"page\"] {\n  background: var(--tempra-color-selected);\n  color: var(--tempra-color-text);\n  font-weight: 500;\n}\n\n.ws-views .count {\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-label);\n  font-weight: 400;\n  font-variant-numeric: tabular-nums;\n}\n\n/* The sheet: the open file on its own card, scrolling inside. */\n.ws-main {\n  grid-area: main;\n  position: relative;\n  min-width: 0;\n  overflow: hidden auto;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-card);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n}\n\n/* A library view or folder in the sheet: a wider column than a concept's. */\n.sheet-page {\n  max-width: 960px;\n  margin: 0 auto;\n  padding: 48px clamp(16px, 5%, 40px) 96px;\n}\n\n/* The library's root: no document open, the sheet blank. */\n.empty {\n  min-height: 50vh;\n}\n\n/* A concept in the sheet: the reader's column. */\n.doc {\n  max-width: var(--tempra-measure);\n  margin: 0 auto;\n  padding: 56px clamp(16px, 5%, 40px) 140px;\n}\n\n.crumbs {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  margin-bottom: 24px;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n}\n\n.crumbs a {\n  color: inherit;\n  text-decoration: none;\n}\n\n.crumbs a:hover {\n  color: var(--tempra-color-text);\n}\n\n.crumbs .here {\n  color: var(--tempra-color-muted);\n}\n\n.doc-head {\n  margin-bottom: 32px;\n}\n\n.doc-title {\n  margin: 0 0 12px;\n  font-family: var(--tempra-font-reader);\n  font-size: var(--tempra-text-title);\n  font-weight: 500;\n  line-height: 1.15;\n  letter-spacing: -0.01em;\n}\n\n.doc-tagline {\n  margin: 0;\n  color: var(--tempra-color-muted);\n  font-family: var(--tempra-font-reader);\n  font-size: var(--tempra-text-reader);\n  line-height: 1.5;\n}\n\n/* The control cluster: a pill that hovers at the sheet's top right while it scrolls. */\n.cluster {\n  position: sticky;\n  top: 12px;\n  z-index: 3;\n  display: flex;\n  gap: 2px;\n  width: max-content;\n  margin: 12px 12px -50px auto;\n  padding: 3px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n}\n\n.cluster-sep {\n  align-self: center;\n  width: 1px;\n  height: 18px;\n  margin: 0 3px;\n  background: var(--tempra-color-border);\n}\n\n/* A newer version exists: the glyph pulses until it is opened. */\n@keyframes tempra-pulse {\n  0%,\n  100% {\n    opacity: 1;\n  }\n\n  50% {\n    opacity: 0.35;\n  }\n}\n\n.new-version {\n  position: relative;\n}\n\n.new-version .icon-button {\n  color: var(--tempra-color-text);\n}\n\n.new-version .icon-button svg {\n  animation: tempra-pulse 1.6s ease-in-out infinite;\n}\n\n.new-version .icon-button[aria-expanded=\"true\"] svg {\n  animation: none;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .new-version .icon-button svg {\n    animation: none;\n  }\n}\n\n/* A short note inside a menu (the new version's who and why). */\n.menu-list p {\n  margin: 4px 10px 6px;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  line-height: 1.45;\n}\n\n/* The panel: one card beside the sheet, its own scroll. */\n.ws-panel {\n  grid-area: panel;\n  min-height: 0;\n  overflow: auto;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-card);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  font-size: var(--tempra-text-ui);\n}\n\n.ws-panel:focus {\n  outline: none;\n}\n\n.panel-head {\n  position: sticky;\n  top: 0;\n  z-index: 1;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 14px 16px 10px;\n  background: var(--tempra-color-bg);\n}\n\n.panel-head h2 {\n  margin: 0;\n  font-size: var(--tempra-text-ui);\n  font-weight: 500;\n}\n\n.panel-head .count {\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n  font-variant-numeric: tabular-nums;\n}\n\n.panel-head .spacer {\n  flex: 1;\n}\n\n.panel-close {\n  width: 24px;\n  height: 24px;\n  padding: 0;\n  border: 0;\n  background: transparent;\n  color: var(--tempra-color-faint);\n  font-size: 14px;\n  line-height: 1;\n}\n\n.panel-close:hover:not(:disabled) {\n  color: var(--tempra-color-text);\n}\n\n.panel-body {\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n  padding: 0 16px 16px;\n}\n\n.panel-body section > :last-child {\n  margin-bottom: 0;\n}\n\n.panel-body ul,\n.panel-body ol {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.panel-foot {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n}\n\n.panel-foot a {\n  color: inherit;\n}\n\n/* A one-line state with a dot (verified, unverified). */\n.state-line {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n  font-size: var(--tempra-text-meta);\n  color: var(--tempra-color-muted);\n}\n\n.state-line::before {\n  content: \"\";\n  flex: none;\n  width: 7px;\n  height: 7px;\n  border: 1px solid var(--tempra-color-text);\n  border-radius: 50%;\n  transform: translateY(-1px);\n}\n\n.state-line.on::before {\n  background: var(--tempra-color-text);\n}\n\n/* Name and value pairs (the Review panel's facts, the Properties panel). */\n.facts {\n  display: grid;\n  grid-template-columns: 6.5rem minmax(0, 1fr);\n  gap: 6px 10px;\n  margin: 0;\n  font-size: var(--tempra-text-meta);\n}\n\n.facts > div {\n  display: contents;\n}\n\n.facts dt {\n  color: var(--tempra-color-faint);\n  font-family: var(--tempra-font-mono);\n  font-size: var(--tempra-text-label);\n  line-height: 1.6;\n}\n\n.facts dd {\n  margin: 0;\n  min-width: 0;\n  overflow-wrap: anywhere;\n}\n\n.facts pre {\n  margin: 0;\n  white-space: pre-wrap;\n}\n\n/* A card in a panel (a work item, the verify form). */\n.inset {\n  padding: 10px 12px;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n  font-size: var(--tempra-text-meta);\n  line-height: 1.45;\n}\n\n.inset .chip {\n  background: var(--tempra-color-bg);\n}\n\n.inset-list {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.verify-form {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n}\n\n.verify-form input {\n  flex: 1 1 8rem;\n  min-width: 0;\n}\n\n/* Contents: a rule down the left, the section in view marked. */\n.toc a {\n  display: block;\n  padding: 4px 0 4px 10px;\n  border-left: 2px solid var(--tempra-color-border);\n  color: var(--tempra-color-muted);\n  text-decoration: none;\n}\n\n.toc a:hover {\n  color: var(--tempra-color-text);\n}\n\n.toc a[aria-current=\"location\"] {\n  border-left-color: var(--tempra-color-text);\n  color: var(--tempra-color-text);\n}\n\n.toc .depth-1 a {\n  padding-left: 22px;\n}\n\n.toc .depth-2 a {\n  padding-left: 34px;\n}\n\n.sources li {\n  display: grid;\n  grid-template-columns: 16px minmax(0, 1fr);\n  gap: 6px;\n  margin-bottom: 10px;\n  font-size: var(--tempra-text-meta);\n  line-height: 1.45;\n}\n\n.sources .num {\n  color: var(--tempra-color-faint);\n}\n\n.sources .meta {\n  display: block;\n  color: var(--tempra-color-faint);\n}\n\n.sources a {\n  color: var(--tempra-color-text);\n}\n\n.linked li {\n  margin-bottom: 4px;\n  font-size: var(--tempra-text-meta);\n}\n\n/* History rows: seq, what and who, when. */\n.history li {\n  display: grid;\n  grid-template-columns: 36px minmax(0, 1fr) auto;\n  gap: 8px;\n  padding: 7px 2px;\n  border-top: 1px solid var(--tempra-color-border);\n  font-size: var(--tempra-text-meta);\n  line-height: 1.4;\n}\n\n.history li > span {\n  min-width: 0;\n}\n\n.history .seq {\n  color: var(--tempra-color-muted);\n  font-variant-numeric: tabular-nums;\n  text-decoration: none;\n}\n\n.history .verify .seq {\n  font-weight: 600;\n}\n\n.history li.current {\n  background: var(--tempra-color-ground);\n}\n\n.history .who {\n  color: var(--tempra-color-muted);\n}\n\n.history .note {\n  display: block;\n  overflow: hidden;\n  color: var(--tempra-color-faint);\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.history .when {\n  color: var(--tempra-color-faint);\n  white-space: nowrap;\n}\n\n.history .when a {\n  color: inherit;\n}\n\n/* ---------- The quick switcher ---------- */\n\n.switcher {\n  width: min(36rem, 90vw);\n  padding: 12px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-card);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  color: var(--tempra-color-text);\n}\n\n.switcher::backdrop {\n  background: light-dark(rgb(20 20 22 / 0.2), rgb(0 0 0 / 0.5));\n}\n\n.switcher-head input {\n  width: 100%;\n  border-radius: var(--tempra-radius-pill);\n}\n\n.switcher [role=\"listbox\"] {\n  margin-top: var(--tempra-space-2);\n}\n\n.switcher [role=\"option\"] {\n  padding: 6px 10px;\n  border-radius: var(--tempra-radius-row);\n  cursor: pointer;\n}\n\n.switcher [role=\"option\"][aria-selected=\"true\"] {\n  background: var(--tempra-color-selected);\n}\n\n/* ---------- Narrow screens ---------- */\n\n/* Under 1100px the panel overlays the sheet, below the cluster so the cluster stays in reach. */\n@media (max-width: 1100px) {\n  .workspace.has-panel {\n    grid-template-columns: 232px minmax(0, 1fr);\n    grid-template-areas:\n      \"header header\"\n      \"sidebar main\";\n  }\n\n  .ws-panel {\n    position: fixed;\n    top: 112px;\n    right: var(--tempra-gutter);\n    bottom: var(--tempra-gutter);\n    z-index: 5;\n    width: min(320px, calc(100vw - 20px));\n  }\n}\n\n/* Under 900px the sidebar is a drawer behind the Files button. */\n@media (max-width: 900px) {\n  .workspace,\n  .workspace.has-panel {\n    grid-template-columns: minmax(0, 1fr);\n    grid-template-areas:\n      \"header\"\n      \"main\";\n  }\n\n  .ws-files {\n    display: inline-flex;\n  }\n\n  .ws-sidebar {\n    position: fixed;\n    top: 48px;\n    bottom: var(--tempra-gutter);\n    left: var(--tempra-gutter);\n    z-index: 6;\n    display: none;\n    width: min(280px, calc(100vw - 20px));\n    padding: 8px;\n    border: 1px solid var(--tempra-color-border);\n    border-radius: var(--tempra-radius-card);\n    background: var(--tempra-color-ground);\n    box-shadow: var(--tempra-shadow);\n  }\n\n  .ws-sidebar.open {\n    display: flex;\n  }\n\n  .ws-sidebar:focus {\n    outline: none;\n  }\n\n  .page {\n    padding-top: 40px;\n  }\n}\n\n/* ---------- Page pieces: lists, tables, forms, the ledger, diffs ---------- */\n\n.new-library {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px;\n  margin: -12px 0 24px;\n  padding: 12px 18px;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  font-size: var(--tempra-text-ui);\n}\n\n.new-library .notice {\n  flex-basis: 100%;\n  margin: 0;\n}\n\n/* A command or URL to copy (the connect pages): an inset that wraps rather than widening the page. */\n.page pre,\n.sheet-page pre {\n  margin: 0 0 var(--tempra-space-3);\n  padding: 10px 14px;\n  border-radius: var(--tempra-radius-row);\n  background: var(--tempra-color-ground);\n  font-size: var(--tempra-text-ui);\n  line-height: 1.55;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\n.sheet-page pre,\n.sheet-page pre.src,\n.sheet-page pre.diff {\n  background: var(--tempra-color-ground);\n}\n\n/* Dates and short facts in a table keep to one line. */\ntable.list td.when,\ntable.list .nowrap {\n  white-space: nowrap;\n}\n\n.table-wrap {\n  overflow-x: auto;\n  margin: 0 0 var(--tempra-space-3);\n}\n\ntable.list {\n  width: 100%;\n  font-size: var(--tempra-text-ui);\n}\n\ntable.list th {\n  padding: 6px 10px;\n  border-bottom: 1px solid var(--tempra-color-border);\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-label);\n  font-weight: 400;\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n}\n\ntable.list td {\n  padding: 10px;\n  border-bottom: 1px solid var(--tempra-color-border);\n}\n\ntable.list td.name a {\n  font-weight: 500;\n}\n\n/* A group of related controls on a page (a form, a list with its actions). */\n.panel-box {\n  margin: 0 0 var(--tempra-space-4);\n  padding: 16px 18px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n}\n\n.panel-box > h2:first-child {\n  margin-top: 0;\n}\n\nform.inline,\nform.filters,\nform.token {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px;\n}\n\n/* The ledger's filters: small labels, inset fields, no box. */\nform.filters {\n  margin: 0 0 var(--tempra-space-3);\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n}\n\nform.filters label {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n}\n\nform.filters input {\n  padding: 4px 10px;\n  border: 0;\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-text);\n}\n\nform.filters input[type=\"text\"] {\n  width: 9rem;\n}\n\nform.filters button {\n  padding: 4px 12px;\n  font-size: var(--tempra-text-meta);\n}\n\nform.token {\n  align-items: flex-start;\n  flex-direction: column;\n}\n\npre.src,\npre.diff {\n  overflow-x: auto;\n  padding: 12px 14px;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n  font-size: var(--tempra-text-meta);\n  line-height: 1.55;\n}\n\npre.src.wrap {\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\npre.diff .add {\n  font-weight: 600;\n}\n\npre.diff .del {\n  color: var(--tempra-color-faint);\n  text-decoration: line-through;\n}\n\npre.diff .hunk,\npre.diff .meta {\n  color: var(--tempra-color-muted);\n}\n\nol.ledger {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.request {\n  padding: 12px 0;\n  border-top: 1px solid var(--tempra-color-border);\n  font-size: var(--tempra-text-ui);\n}\n\n.req-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  gap: 4px 8px;\n}\n\n.request .note {\n  margin: 4px 0;\n  color: var(--tempra-color-muted);\n}\n\nul.events {\n  margin: 4px 0 0;\n  padding: 0;\n  list-style: none;\n  font-size: var(--tempra-text-meta);\n}\n\n.op {\n  display: inline-block;\n  min-width: 3.5em;\n  color: var(--tempra-color-muted);\n  font-family: var(--tempra-font-mono);\n  font-size: var(--tempra-text-label);\n}\n\n/* ---------- Notifications (TEMPRA-72, TEMPRA-73): counts, the inbox, mentions ---------- */\n\n/* The headers' Inbox link and its unread count: a number, no colour. */\n.inbox-link {\n  display: inline-flex;\n  align-items: baseline;\n  gap: 6px;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n  text-decoration: none;\n}\n\n.inbox-link:hover {\n  color: var(--tempra-color-text);\n}\n\n.inbox-link .count,\n.lib-list .tally {\n  color: var(--tempra-color-faint);\n  font-variant-numeric: tabular-nums;\n}\n\n/* A library's tally in the list: for you, new, open threads. */\n.lib-list .tally {\n  float: right;\n  font-size: var(--tempra-text-ui);\n  font-weight: 400;\n}\n\n.inbox-list {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.inbox-list li {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  gap: 4px 12px;\n  padding: 12px 18px;\n  border-radius: var(--tempra-radius-box);\n}\n\n.inbox-list li:hover {\n  background: var(--tempra-color-hover);\n}\n\n.inbox-list .what {\n  flex: 1 1 20rem;\n}\n\n.inbox-list .unread .what a {\n  font-weight: 600;\n}\n\n.inbox-list .when {\n  font-size: var(--tempra-text-meta);\n}\n\n.inbox-list .excerpt {\n  flex-basis: 100%;\n  margin: 0;\n  color: var(--tempra-color-muted);\n}\n\n/* The comment box with its @ suggestions under it. */\n.mention-box {\n  position: relative;\n}\n\n.mention-list [aria-selected=\"true\"] {\n  background: var(--tempra-color-hover);\n}\n";

